 private static void replay(String path)throws Exception{
  ChambersDemonstration.Saved saved;try(java.io.Reader reader=new java.io.InputStreamReader(new java.io.FileInputStream(path),java.nio.charset.StandardCharsets.UTF_8)){saved=new com.google.gson.Gson().fromJson(reader,ChambersDemonstration.Saved.class);}
  check(saved!=null&&"orion-chambers-demonstration-v1".equals(saved.schema),"recording schema");OlmFighter.Profile seedProfile=new OlmFighter.Profile();seedProfile.mageHands.add(7553);seedProfile.meleeHands.add(7555);seedProfile.heads.add(7554);OlmTargetNetwork network=new OlmTargetNetwork();int seeded=network.seed(saved,seedProfile);check(seeded>=5,"real demonstrated attacks seed neural target model");System.out.println("Neural target imitation seeded from "+seeded+" recorded attacks; training fit is not live combat validation.");OlmPhaseTracker p=new OlmPhaseTracker();int third=-1;
  for(ChambersDemonstration.Frame f:saved.frames)for(int[] n:f.npcs)if(n[0]==7553||n[0]==7555){p.observe(n[0]==7553,n[6],n[1],n[2],n[4]>0,n[4]==0);if(third<0&&p.magicKills()>=2&&p.meleeKills()>=2)third=f.tick;}
  check(p.magicKills()==3&&p.meleeKills()==3&&third==605,"second demonstration confirms three pairs and third-phase threshold");System.out.println("Observed demonstration replay: mage deaths=3, melee deaths=3; phase-three threshold at recorded tick 605. This verifies detection on that recording, not live fighter performance.");
 }
